def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast-path: count recent behavior
    last_my, last_opp = history[-1]
    if n >= 2:
        prev_my, prev_opp = history[-2]
    else:
        prev_my, prev_opp = ('C', 'C')

    # Opponent cooperation stats
    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c
    coop_rate = opp_c / n

    # Detect a clean reciprocal opponent early via recent mirroring
    # (opponent mirrors own previous move)
    if n >= 4:
        mir = 0
        tot = 0
        start = n - 6
        if start < 1:
            start = 1
        for i in range(start, n):
            if history[i][1] == history[i-1][0]:
                mir += 1
            tot += 1
        if tot > 0 and mir / tot >= 0.8 and opp_d <= n * 0.35:
            return 'C'

    # Always-cooperative opponent: stay cooperative (no exploitation probing)
    if opp_d == 0:
        return 'C'

    # Always-defecting opponent: defect
    if opp_c == 0:
        return 'D'

    # Heavy sustained defection
    if opp_d >= n * 0.85 and n >= 5:
        return 'D'

    # Last few rounds: if opponent is mostly cooperative, defect at the very end
    remaining = 100 - n
    if remaining <= 2:
        if coop_rate >= 0.5:
            return 'D'
        return 'D'

    # Early rounds: cooperate to establish trust
    if n <= 3:
        return 'C'

    # Count consecutive opponent defections at the tail
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_d += 1
        else:
            break

    # Count consecutive opponent cooperations at the tail
    consec_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_c += 1
        else:
            break

    # Strong retaliation against sustained defection: need to recover from
    # four_D_TFT probes (which start with 4 D's). Punish long enough to
    # discourage exploitation, but not forever.
    if consec_d >= 2:
        # If our own recent play has been defecting too, attempt controlled reset
        # only after a long run to avoid lock-in against all-defectors.
        if consec_d >= 4:
            # Against genuine exploiters, keep defecting. Against TFT-like
            # opponents that opened with defections, cooperation won't help
            # until they stop, so retaliate firmly.
            if opp_d < n * 0.5 and consec_d <= 4:
                # Opponent mostly cooperated historically but did a short
                # defection burst; forgive after a couple retaliations.
                if rng.random() < 0.5:
                    return 'C'
                return 'D'
            return 'D'
        # consec_d is 2 or 3: retaliate but allow occasional forgiveness
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last. Reward cooperation.
    if last_opp == 'C':
        # If we defected last and they still cooperated, they are forgiving.
        # Continue cooperating to maintain mutual CC.
        if last_my == 'D':
            return 'C'
        # If the opponent has a moderate defection rate, occasionally retaliate
        # to discourage exploitation.
        if n >= 12 and coop_rate < 0.6:
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        # Mostly cooperative relationship: cooperate steadily.
        return 'C'

    # Opponent defected last (single defection, since consec_d < 2)
    # Retaliate once, then forgive.
    if last_my == 'D':
        # We already retaliated; return to cooperation to rebuild.
        return 'C'
    # We cooperated and got defected on: retaliate once.
    return 'D'
